package com.manishrawat.realestate.thread; import java.util.concurrent.*; public class NotificationWorker implements Runnable { private static final BlockingQueue<String> QUEUE=new LinkedBlockingQueue<>(); public static void add(String s){QUEUE.offer(s);} public static synchronized int pending(){return QUEUE.size();} public void run(){while(!Thread.currentThread().isInterrupted()){try{QUEUE.take();}catch(InterruptedException e){Thread.currentThread().interrupt();}}} }
